∀ {ι : Type u_1} [inst : Fintype ι] [inst_1 : DecidableEq ι] [Nonempty ι] (β : ℝ) {Δ : ℝ → Matrix ι ι ℂ}
  {dΔ K : Matrix ι ι ℂ} {t : ℝ},
  HasDerivAt Δ dΔ t →
    (∀ᶠ (s : ℝ) in nhds t, star (Δ s) = Δ s) →
      star K = -K →
        have E := NormedSpace.exp (-β • Δ t);
        have X := dΔ - D0.Algebra.MovingProjectorTransport.comm K (Δ t);
        have ρ := D0.Analysis.MovingProjectorBookPrice.matrixThermalState β (Δ t);
        star E.trace = E.trace ∧
          star (E * X).trace = (E * X).trace ∧
            ρ.trace = 1 ∧ ↑(-(E * X).trace.re / D0.Analysis.matrixHeatPartition β (Δ t)) = -(ρ * X).trace

∀ {ι : Type u_1} [inst : Fintype ι] [inst_1 : DecidableEq ι] (β z : ℝ) (P U Δ : Matrix ι ι ℂ),
  star Δ = Δ →
    have ρ := D0.Analysis.MovingProjectorBookPrice.matrixThermalState β Δ;
    have C := D0.Algebra.MovingProjectorTransport.cut P U;
    have F := star C * C;
    have R := (1 - ↑z • F)⁻¹;
    star (ρ * Δ).trace = (ρ * Δ).trace ∧ star (R * F).trace = (R * F).trace
